  drawSprite(BOSS_SPRITES[(frameCount / 12 | 0) % 2], 22, 134, BOSS_COLORS);
  drawText("150", 62, 140, "#ffffff");
  drawText("400 800 1600", 62, 150, "#ffff00");

  if ((frameCount / 30) % 2 === 0) {
    drawCenteredText("PRESS ENTER TO START", 220, "#ffffff");
  }

  drawCenteredText("ARROWS/A/D MOVE  SPACE FIRE  P PAUSE  M MUTE", 250, "#888888");

  if (muted) drawText("MUTE", W - 44, 24, "#ff8888");
}

function renderStageIntro() {
  drawHUD();
  if (isChallengingStage(stage)) {
    drawCenteredText("CHALLENGING STAGE", 140, "#ffff00");
  } else {
    drawCenteredText("STAGE " + stage, 140, "#ffffff");
  }
}

function renderPlaying() {
  drawHUD();

  for (const e of enemies) drawEnemy(e);
  drawBullets();
  drawPlayer();
  drawFreedShips();

  for (const ex of explosions) drawExplosion(ex);

  if (player.respawnTimer > 0) {
    drawCenteredText("READY", 180, "#ffffff");
  }

  drawReserveShips();
  drawStageBadges();

  if (paused) {
    drawCenteredText("PAUSE", 140, "#ffffff");
  }

  if (muted) drawText("MUTE", W - 44, 24, "#ff8888");
}

function renderStageClear() {
  drawHUD();
  drawCenteredText("STAGE CLEAR", 140, "#00ffff");
  drawReserveShips();
  drawStageBadges();
}

function renderChallengeResults() {
  drawHUD();

  drawCenteredText("CHALLENGING STAGE", 80, "#ffff00");
  drawText("NUMBER OF HITS", 40, 120, "#ffffff");
  drawText(String(challengeHits), 150, 120, "#ffff00");

  drawText("BONUS", 40, 140, "#ffffff");
  drawText(String(challengeBonus), 150, 140, "#ffff00");

  if (challengeHits >= 40) {
    drawCenteredText("PERFECT!", 170, "#ff00ff");
  }

  drawCenteredText("PRESS ENTER TO CONTINUE", 220, "#ffffff");
}

function renderGameOver() {
  drawHUD();

  if (stateTimer > 180) {
    drawCenteredText("GAME OVER", 130, "#ff0000");
  } else {
    const ratio = shotsFired > 0 ? Math.floor((hits / shotsFired) * 100) : 0;

    drawCenteredText("HIT-MISS RATIO", 80, "#ffffff");
    drawText("SHOTS FIRED", 40, 120, "#ffffff");
    drawText(String(shotsFired), 150, 120, "#ffff00");

    drawText("NUMBER OF HITS", 40, 140, "#ffffff");
    drawText(String(hits), 150, 140, "#ffff00");

    drawText("RATIO", 40, 160, "#ffffff");
    drawText(String(ratio) + "%", 150, 160, "#ffff00");

    drawCenteredText("PRESS ENTER", 220, "#ffffff");
  }
}

function render() {
  ctx.setTransform(scale, 0, 0, scale, 0, 0);
  ctx.fillStyle = "#000000";
  ctx.fillRect(0, 0, W, H);

  drawStars();

  if (state === "title") renderTitle();
  else if (state === "stageIntro") renderStageIntro();
  else if (state === "playing") renderPlaying();
  else if (state === "stageClear") renderStageClear();
  else if (state === "challengeResults") renderChallengeResults();
  else if (state === "gameOver") renderGameOver();
}

/* -------------------------------------------------------------------------
   Main update.
-------------------------------------------------------------------------- */

function updatePlaying() {
  updatePlayer();
  updateEnemies();
  updatePlayerBullets();
  updateEnemyBullets();
  updateFreedShips();
  updateExplosions();
  checkPlayerCollisions();

  // Stage progression for challenging stage.
  if (isChallengingStage(stage)) {
    if (challengeWave < 5) {
      challengeWaveTimer--;
      if (challengeWaveTimer <= 0) {
        spawnChallengeWave();
      }
    } else if (enemies.length === 0) {
      if (challengeHits >= 40) challengeBonus += 10000;
      state = "challengeResults";
      stateTimer = 300;
    }
  }

  // Dive scheduling.
  if (formationComplete && !isChallengingStage(stage)) {
    diveTimer--;
    if (diveTimer <= 0) {
      startDiveEvent();
      diveTimer = Math.max(22, 150 - stage * 9 + Math.random() * 60);
    }
  }
}

function update() {
  frameCount++;
  updateStars();

  if (paused && state === "playing") return;

  if (state === "title") {
    stateTimer++;
  } else if (state === "stageIntro") {
    stateTimer--;
    if (stateTimer === 119) sfxStageJingle();
    if (stateTimer <= 0) {
      initStageEnemies();
      state = "playing";
      stateTimer = 0;
    }
  } else if (state === "playing") {
    updatePlaying();
  } else if (state === "stageClear") {
    stateTimer--;
    if (stateTimer <= 0) {
      startStage(stage + 1);
    }
  } else if (state === "challengeResults") {
    stateTimer--;
    if (stateTimer <= 0) {
      startStage(stage + 1);
    }
  } else if (state === "gameOver") {
    stateTimer--;
    if (stateTimer <= 0) {
      state = "title";
      stateTimer = 0;
    }
  }
}

/* -------------------------------------------------------------------------
   Fixed-timestep loop.
-------------------------------------------------------------------------- */

let last = performance.now();
let acc = 0;

function loop(now) {
  acc += now - last;
  last = now;

  // Avoid spiral of death after tab switch.
  if (acc > 250) acc = 250;

  while (acc >= STEP_MS) {
    update();
    acc -= STEP_MS;
  }

  render();
  requestAnimationFrame(loop);
}

requestAnimationFrame(loop);
</script>
